    gl.uniform2f(U("tx"),1/g.vw,1/g.vh);gl.uniform2f(U("ms"),g.vw/g.SW,g.vh/g.SH);gl.uniform2f(U("mo"),g.ox/g.SW,(g.SH-g.oy-g.vh)/g.SH);
