      if(light&&!nearLeg.has(x+","+y)){g.fillStyle=hexc([r,gg,bb]);g.globalAlpha=lum>200?.85:.55;g.fillRect(x,y,1,1);g.globalAlpha=1}
      if(y<Math.min(SKY[x],x>=290?50:999)-1&&x>200&&lum>140){let n=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dy)continue;const q=at(Math.min(SW-1,Math.max(0,x+dx)),Math.min(SH-1,Math.max(0,y+dy)));if((q[0]+q[1]+q[2])/3>120)n++}if(n<=1)A.stars.push({x,y,c:[r,gg,bb],sp:.6+R()*2.4,ph:R()*7})}
      const warm=r>190&&gg>110&&bb<170;
      if(inR(x,y,LANT)&&r>200&&gg<120&&bb<110)A.lant.push({x,y,c:[r,gg,bb],ph:R()*7});
      if(inR(x,y,FAIRY)&&warm&&lum>170)A.fairy.push({x,y,c:[r,gg,bb],ph:R()*7});
