  const OFF=.04;                                         // unlit glass still catches a little light
  /* each tube: a timeline of steps [duration, level, tint, ramp]; after the last step the level holds */
  const T=[0,1,2,3].map(k=>({k,segs:[],t0:0,v:OFF,c:0,next:0,busy:0}));
  const MEAN=[28,34,22,11];                              // seconds between faults, per tube
