    cold=document.createElement("canvas");cold.width=W0;cold.height=H0;   // the star while the mercury is still cold
    const cx=cold.getContext("2d");cx.drawImage(parts[1],0,0);cx.globalCompositeOperation="source-atop";cx.fillStyle="rgb(168,120,255)";cx.fillRect(0,0,W0,H0);
