  const nxt = hs[cur + 1] ? hs[cur + 1].getBoundingClientRect().top : r.bottom;
  const f = Math.max(0, Math.min(1, (y - sec.top) / Math.max(1, nxt - sec.top)));
  const b = items[cur + 1] ? items[cur + 1].getBoundingClientRect().top : o.bottom;
