  const lockTo = e => { const a = e.target.closest("a[href^='#']"); if (!a) return; const i = hs.findIndex(h => "#" + h.id === a.getAttribute("href")); if (i < 0) return; lockI = i; lockT = Date.now() + 6e4; lockAt = Date.now(); req(); };
